/// Shelf integration for axle.
library;

import 'package:axle_core/axle_core.dart';
import 'package:shelf/shelf.dart';
import 'package:shelf_static/shelf_static.dart';

/// Creates a Shelf handler that serves the generated spec and Swagger UI.
///
/// The returned handler responds to `GET` requests at [specPath] and
/// [docsPath]. It returns `404 Not Found` for every other path, so it can be
/// combined with a router or a [Cascade].
///
/// Pass [swaggerUiDirectory] to serve the assets generated by
/// `axle gen` from that directory. The UI then loads assets from
/// [swaggerUiPath]. When [swaggerUiDirectory] is omitted, the UI uses
/// [swaggerUiUrl], which defaults to the pinned CDN distribution.
Handler axleDocsHandler({
  required String spec,
  String specPath = '/openapi.json',
  String docsPath = '/docs',
  String? title,
  String swaggerUiUrl = defaultSwaggerUiUrl,
  String? swaggerUiDirectory,
  String swaggerUiPath = '/docs-assets',
  bool noCache = true,
}) {
  final localAssetsPath = swaggerUiDirectory == null
      ? null
      : _normalizePrefix(swaggerUiPath);
  final docs = AxleDocs(
    spec: spec,
    specPath: specPath,
    docsPath: docsPath,
    title: title,
    swaggerUiUrl: localAssetsPath ?? swaggerUiUrl,
    noCache: noCache,
  );
  if (localAssetsPath != null &&
      (localAssetsPath == '/' ||
          localAssetsPath == docs.specPath ||
          localAssetsPath == docs.docsPath)) {
    throw ArgumentError.value(
      swaggerUiPath,
      'swaggerUiPath',
      'must not be `/`, the spec path, or the docs path.',
    );
  }
  final specHandler = openApiJsonHandler(docs);
  final uiHandler = swaggerUiHandler(docs);
  final assetsHandler = swaggerUiDirectory == null
      ? null
      : swaggerUiAssetsHandler(
          swaggerUiDirectory,
          pathPrefix: localAssetsPath!,
          noCache: noCache,
        );

  return (Request request) {
    if (request.method != 'GET') return Response.notFound('Not found');
    final path = _requestPath(request);
    if (path == docs.specPath) return specHandler(request);
    if (path == docs.docsPath) return uiHandler(request);
    if (assetsHandler != null &&
        (path == localAssetsPath || path.startsWith('$localAssetsPath/'))) {
      return assetsHandler(request);
    }
    return Response.notFound('Not found');
  };
}

/// Creates a Shelf handler for an already configured [AxleDocs] payload.
Handler openApiJsonHandler(AxleDocs docs) {
  return (Request request) => Response.ok(
    docs.specJson,
    headers: _headers(docs.headers, contentType: 'application/json'),
  );
}

/// Creates a Shelf handler for the Swagger UI page of [docs].
Handler swaggerUiHandler(AxleDocs docs) {
  return (Request request) => Response.ok(
    docs.uiHtml,
    headers: _headers(docs.headers, contentType: 'text/html; charset=utf-8'),
  );
}

/// Creates a Shelf handler that serves Swagger UI assets from [directory].
///
/// [directory] is the `generate.output.ui` directory produced by `axle gen`.
/// The returned handler serves files below [pathPrefix] and returns `404` for
/// requests outside that prefix. Path traversal and symlinks pointing outside
/// [directory] are rejected by `shelf_static`.
Handler swaggerUiAssetsHandler(
  String directory, {
  String pathPrefix = '/docs-assets',
  bool noCache = true,
}) {
  final prefix = _normalizePrefix(pathPrefix);
  final staticHandler = createStaticHandler(
    directory,
    defaultDocument: 'index.html',
  );

  return (Request request) async {
    if (request.method != 'GET') return Response.notFound('Not found');
    final path = _requestPath(request);
    if (path != prefix && !path.startsWith('$prefix/')) {
      return Response.notFound('Not found');
    }
    final response = await staticHandler(
      request.change(path: prefix.substring(1)),
    );
    if (!noCache) return response;
    return response.change(
      headers: {...response.headers, 'cache-control': 'no-store'},
    );
  };
}

Map<String, Object> _headers(
  Map<String, String> values, {
  required String contentType,
}) {
  return {'content-type': contentType, ...values};
}

String _requestPath(Request request) {
  return _normalizePath(request.requestedUri.path);
}

String _normalizePath(String path) {
  final trimmed = path.trim();
  if (trimmed.isEmpty) return '/';
  return trimmed.startsWith('/') ? trimmed : '/$trimmed';
}

String _normalizePrefix(String path) {
  final normalized = _normalizePath(path);
  if (normalized.length > 1 && normalized.endsWith('/')) {
    return normalized.substring(0, normalized.length - 1);
  }
  return normalized;
}
